drop policy if exists evaluations_manage on public.contractor_evaluations;
create policy evaluations_insert on public.contractor_evaluations for insert to authenticated with check ((select private.is_acredita_staff()) or exists(select 1 from public.accreditations a where a.id=accreditation_id and (select private.can_manage_project(a.project_id))));
create policy evaluations_update on public.contractor_evaluations for update to authenticated using ((select private.is_acredita_staff()) or exists(select 1 from public.accreditations a where a.id=accreditation_id and (select private.can_manage_project(a.project_id)))) with check ((select private.is_acredita_staff()) or exists(select 1 from public.accreditations a where a.id=accreditation_id and (select private.can_manage_project(a.project_id))));
create policy evaluations_delete on public.contractor_evaluations for delete to authenticated using ((select private.is_acredita_staff()) or exists(select 1 from public.accreditations a where a.id=accreditation_id and (select private.can_manage_project(a.project_id))));

