drop policy if exists credentials_manage on public.access_credentials;
create policy credentials_insert on public.access_credentials for insert to authenticated with check ((select private.is_acredita_staff()) or (select private.can_manage_project(project_id)));
create policy credentials_update on public.access_credentials for update to authenticated using ((select private.is_acredita_staff()) or (select private.can_manage_project(project_id))) with check ((select private.is_acredita_staff()) or (select private.can_manage_project(project_id)));
create policy credentials_delete on public.access_credentials for delete to authenticated using ((select private.is_acredita_staff()) or (select private.can_manage_project(project_id)));
